const normalize=text=>String(text||'').normalize('NFKC').replace(/[\u064b-\u065f\u0670\u06d6-\u06ed\u0640]/g,'').replace(/ى/g,'ي').replace(/[^\u0621-\u064a]/g,'');
export function recordingFor(kind,id,arabic){return recordings.find(r=>r.targets.some(t=>t.kind===kind&&t.id===id)&&normalize(r.arabic)===normalize(arabic))||null}
export function allowedLessonAudio(url){return typeof url==='string'&&(url.startsWith('https://cdn.islamic.network/quran/audio/')||recordings.some(r=>r.url===url))}
export const recordingTargets=Object.freeze(recordings.flatMap(r=>r.targets.map(t=>({...t,url:r.url}))));
